 12	public final class CircularQueueTest {
 13	
 14	    private CircularQueueTest() {
 15	    }
 16	
 17	    public static void main(String[] args) {
 18	        testBasicQueueOperations();
 19	        testWrapAroundBehavior();
 20	        testCapacityBoundaries();
 21	        testClearAndRemainingCapacity();
 22	        testIteratorTraversalAndFailFastBehavior();
 23	        testNullElementsAreRejected();
 24	
 25	        System.out.println("All CircularQueue tests passed.");
 26	    }
