 28	    private static void testBasicQueueOperations() {
 29	        BoundedQueue<Integer> queue = new CircularQueue<>(3);
 30	
 31	        queue.enqueue(10);
 32	        queue.enqueue(20);
 33	
 34	        assertEquals(2, queue.size(), "enqueue should increase the size");
 35	        assertEquals(1, queue.remainingCapacity(), "remaining capacity should decrease after enqueue");
 36	        assertEquals(Integer.valueOf(10), queue.peek(), "peek should return the front element");
 37	        assertEquals(Integer.valueOf(10), queue.peekFront(), "peekFront should return the front element");
 38	        assertEquals(Integer.valueOf(20), queue.peekRear(), "peekRear should return the rear element");
 39	        assertEquals(Integer.valueOf(10), queue.dequeue(), "dequeue should remove from the front");
 40	        assertEquals(Integer.valueOf(20), queue.poll(), "poll should remove and return the next element");
 41	        assertNull(queue.poll(), "poll should return null when the queue is empty");
 42	        assertThrows(IllegalStateException.class, queue::dequeue, "dequeue should throw when the queue is empty");
 43	    }
 44	
 45	    private static void testWrapAroundBehavior() {
 46	        BoundedQueue<Integer> queue = new CircularQueue<>(3);
 47	
 48	        queue.enqueue(1);
 49	        queue.enqueue(2);
 50	        queue.enqueue(3);
 51	        queue.dequeue();
 52	        queue.enqueue(4);
 53	
 54	        assertEquals("[2, 3, 4]", queue.toString(), "wrap-around should preserve iteration order");
 55	        assertEquals(Integer.valueOf(2), queue.peekFront(), "front should advance after dequeue");
 56	        assertEquals(Integer.valueOf(4), queue.peekRear(), "rear should track wrapped insertion");
 57	    }
 58	
 59	    private static void testCapacityBoundaries() {
 60	        BoundedQueue<Integer> queue = new CircularQueue<>(2);
 61	
 62	        assertTrue(queue.offer(7), "offer should succeed when there is room");
 63	        assertTrue(queue.offer(8), "offer should succeed until the queue is full");
 64	        assertFalse(queue.offer(9), "offer should return false when the queue is full");
 65	        assertThrows(IllegalStateException.class, () -> queue.enqueue(9), "enqueue should throw when the queue is full");
 66	        assertEquals(0, queue.remainingCapacity(), "remaining capacity should be zero when full");
 67	    }
 68	
 69	    private static void testClearAndRemainingCapacity() {
 70	        BoundedQueue<String> queue = new CircularQueue<>(2);
 71	
 72	        queue.enqueue("a");
 73	        queue.enqueue("b");
 74	        queue.clear();
 75	
 76	        assertTrue(queue.isEmpty(), "clear should empty the queue");
 77	        assertEquals(2, queue.remainingCapacity(), "clear should restore the full remaining capacity");
 78	        assertEquals("[]", queue.toString(), "clear should reset the string representation");
 79	    }
