 81	    private static void testIteratorTraversalAndFailFastBehavior() {
 82	        BoundedQueue<Integer> queue = new CircularQueue<>(4);
 83	
 84	        queue.enqueue(5);
 85	        queue.enqueue(6);
 86	        queue.enqueue(7);
 87	
 88	        StringBuilder builder = new StringBuilder();
 89	        for (int value : queue) {
 90	            if (builder.length() > 0) {
 91	                builder.append(',');
 92	            }
 93	            builder.append(value);
 94	        }
 95	        assertEquals("5,6,7", builder.toString(), "iterator should traverse from head to tail");
 96	
 97	        Iterator<Integer> iterator = queue.iterator();
 98	        assertTrue(iterator.hasNext(), "iterator should have elements before mutation");
 99	        queue.dequeue();
100	        assertThrows(
101	                ConcurrentModificationException.class,
102	                iterator::next,
103	                "iterator should fail fast after queue mutation");
104	    }
