106	    private static void testNullElementsAreRejected() {
107	        BoundedQueue<String> queue = new CircularQueue<>(1);
108	
109	        assertThrows(NullPointerException.class, () -> queue.offer(null), "offer should reject null elements");
110	        assertThrows(NullPointerException.class, () -> queue.enqueue(null), "enqueue should reject null elements");
111	    }
112	}

