 52	        return peekFront();
 53	    }
 54	
 55	    public T getRear() {
 56	        return peekRear();
 57	    }
 58	
 59	    public boolean isEmpty() {
 60	        return size == 0;
 61	    }
 62	
 63	    @Override
 64	    public boolean offer(T value) {
 65	        Objects.requireNonNull(value, "Queue elements must be non-null.");
 66	
 67	        if (isFull()) {
 68	            return false;
 69	        }
 70	
 71	        insertAtTail(value);
 72	        recordMutation();
